tion['hours']) ?><br>Sunday: <?= U::e($station['sunday']) ?></p><p class="muted mt-2">Bring your empty containers. Wait for the station to confirm your order is ready before collecting.</p></section><fieldset><legend class="section-title" data-option-title>2. Delivery option</legend><p class="muted mb-3"><span data-timing-question>When do you want your order delivered?</span></p><label class="flex gap-3 mb-3"><input type="radio" name="delivery" value="asap" checked class="accent-cyan-600"><span><strong data-asap-title>As soon as possible (ASAP)</strong><span class="block muted"><span data-asap-copy>For the next available delivery.</span></span></span></label><label class="flex gap-3"><input type="radio" name="delivery" value="scheduled" class="accent-cyan-600"><span><strong data-schedule-title>Schedule delivery for later</strong><span class="block muted">Subject to station confirmation.</span></span></label><div class="grid sm:grid-cols-2 gap-3 mt-3"><?= U::field('Preferred date', 'date', '2026-11-02', 'date', ['min' => '2026-11-02']) ?><?= U::select('Preferred time', 'time', ['10:00' => '10:00 AM', '13:00' => '1:00 PM', '15:00' => '3:00 PM'], '10:00') ?></div></fieldset><div><?= U::title('3. Empty containers to return','bottle','mb-3') ?><div class="flex items-center gap-2"><?= U::btn('−', '', 'secondary', '', ['data-step' => '-1', 'data-counter' => 'return-quantity', 'aria-label' => 'Return fewer containers']) ?><input type="number" name="returns" id="return-quantity" min="0" max="40" value="<?= $quote['returns'] ?>" required class="field w-24 text-center" aria-label="Empty containers to return"><?= U::btn('+', '', 'secondary', '', ['data-step' => '1', 'data-counter' => 'return-quantity', 'aria-label' => 'Return more containers']) ?></div></div><div><h2 class="section-title mb-3"><span data-notes-title>4. Delivery notes (optional)</span></h2><?= U::textarea('Instructions for your delivery team', 'notes', '', ['maxlength' => '200', 'placeholder' => 'Look for the blue gate. Please call upon arrival.']) ?></div><fieldset><legend class="section-title mb-3">5. Payment method</legend><label class="flex items-center gap-3 rounded-lg border border-line bg-foam p-4"><input type="radio" name="payment" value="cash" checked required class="accent-cyan-600"><span><strong><span data-payment-title>Cash on delivery</span></strong><span class="block muted"><span data-payment-copy>Pay when your order is delivered.</span></span></span></label></fieldset></section></div>
